import{_ as o,o as a,c as l,ag as e}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"语音词库","description":"","frontmatter":{},"headers":[],"relativePath":"voice/vocabulary.md","filePath":"voice/vocabulary.md","lastUpdated":null}'),r={name:"voice/vocabulary.md"};function i(s,t,n,c,u,d){return a(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="语音词库" tabindex="-1">语音词库 <a class="header-anchor" href="#语音词库" aria-label="Permalink to &quot;语音词库&quot;">​</a></h1><blockquote><p>添加你常用的专有名词、人名、术语，录音转写不再写错</p></blockquote><p>录音转写时，专有名词、人名、行业术语最容易被误识别——&quot;柳比歇夫&quot;可能变成&quot;刘比谢夫&quot;，&quot;GetSeed&quot;可能变成&quot;get seed&quot;。</p><p>语音词库帮你解决这个问题：把你常用的词提前告诉 AI，录音转写时 AI 就会优先识别这些词，大幅提升准确率。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>行业术语</strong>：金融、法律、医疗、科技等领域的专业词汇，避免转写时被识别成同音别字</li><li><strong>人名识别</strong>：同事、客户、合作伙伴的姓名，特别是生僻字或容易混淆的名字</li><li><strong>产品/品牌名</strong>：公司内部产品代号、品牌名称、项目代号等专有名词</li><li><strong>外来词汇</strong>：英文缩写、外语人名、中英混用的表达，帮助 AI 正确识别</li><li><strong>学术场景</strong>：课程名称、学术概念、文献中的特定术语</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>智能推荐热词</strong>：AI 基于你已有的笔记内容，自动分析并推荐高频出现但可能识别不准的词汇，一键添加即可</li><li><strong>自定义添加</strong>：手动创建并添加你需要的热词，输入正确写法，AI 在后续转写时会优先匹配</li><li><strong>提升识别率</strong>：词库中的词会在语音识别时被加权，遇到同音词时优先识别为你设定的正确写法</li></ul><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li>打开 App，点首页右上角菜单，点头像进入「我的账号」页面</li><li>在常用操作区域点击「语音词库」</li><li><strong>智能推荐</strong>：AI 会基于你的笔记内容分析出高频热词，点击即可一键添加</li><li><strong>自定义添加</strong>：输入你需要的词汇（如人名、术语、品牌名），保存后即刻生效</li><li>设置完成后无需其他操作，后续录音转写时 AI 会自动应用词库</li></ol><div class="tip custom-block"><p class="custom-block-title">小技巧</p><p>录音中，点击右上角设置按钮，也可直接进入语音词库。</p></div>',11)])])}const h=o(r,[["render",i]]);export{g as __pageData,h as default};
